SET DEFINE OFF;
DECLARE
  v_count NUMBER;
BEGIN
  FOR ns IN 511..515 LOOP
    SELECT COUNT(*) INTO v_count FROM INSUDB.MASTERSHEET WHERE NSHEET = ns;
    IF v_count > 0 THEN
      DELETE FROM INSUDB.MASTERSHEET WHERE NSHEET = ns;
    END IF;
  END LOOP;
END;
